"""Synthetic package creation leaves the order in packing status."""
def complete(repo, order_id):
    order = repo.get("orders", order_id)
    picks = repo.find("picks", lambda row: row["order_id"] == order_id and row["status"] == "done")
    if order is None or order["status"] != "packing" or not picks:
        raise ValueError("packing not allowed")
    if repo.find("packages", lambda row: row["order_id"] == order_id):
        raise ValueError("package exists")
    return repo.insert("packages", {"order_id": order_id, "status": "packed"})

"""Synthetic requested/approved return records; no automatic refund/restock."""
def request(repo, order_id, reason):
    order = repo.get("orders", order_id)
    if order is None or order["status"] != "delivered" or not reason.strip():
        raise ValueError("return request rejected")
    return repo.insert("returns", {"order_id": order_id, "reason": reason, "status": "requested"})

def approve(repo, return_id):
    row = repo.get("returns", return_id)
    if row is None or row["status"] != "requested":
        raise ValueError("approval rejected")
    row["status"] = "approved"
    return row

"""Synthetic merchant accounting; booked does not mean bank transfer."""
def accrue(repo, order_id):
    order = repo.get("orders", order_id)
    if order["status"] != "delivered":
        raise ValueError("settlement requires delivery")
    return repo.insert("settlements", {"order_id": order_id, "merchant_id": order["merchant_id"], "amount_cents": order["total_cents"], "status": "pending"})

def close(repo, merchant_id):
    rows = repo.find("settlements", lambda row: row["merchant_id"] == merchant_id and row["status"] == "pending")
    total = sum(row["amount_cents"] for row in rows)
    for row in rows:
        row["status"] = "booked"
    return {"merchant_id": merchant_id, "amount_cents": total}
